pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }
    function testFuzz_property(address newOwner) public {
        // Rule (universal): no call to transferOwnership, whatever newOwner the fuzzer picks,
        // can ever leave c.owner() == address(0). The reference enforces this by reverting on
        // the zero address; the mutant (zero-address check deleted) accepts it, so for the
        // input newOwner == address(0) the mutant ends with owner() == address(0).
        try c.transferOwnership(newOwner) {
            // transfer succeeded
        } catch {
            // transfer reverted; owner must remain non-zero either way
        }
        assertTrue(c.owner() != address(0));
    }
}
